  for(const record of [
    {id:'demo_item_hoops',name:'[DEMO] Brass Hoops',sku:'DEMO-HOOP',price:28,category_id:'demo_category_jewelry',photo:null,track_quantity:true,quantity:9,low_stock_at:3,active:true},
    {id:'demo_item_candle',name:'[DEMO] Citrus Candle',sku:'DEMO-CANDLE',price:18,category_id:'demo_category_home',photo:null,track_quantity:true,quantity:5,low_stock_at:2,active:true},
    {id:'demo_item_tote',name:'[DEMO] Market Tote',sku:'DEMO-TOTE',price:22,category_id:'demo_category_home',photo:null,track_quantity:false,quantity:0,low_stock_at:0,active:true}
  ])await putDemo('items',{...record,created_at:created,updated_at:activeAt});
  await putDemo('customers',{id:'demo_customer_maya',name:'[DEMO] Maya Chen',email:'maya@example.test',phone:'555-0100',notes:'Demo customer for exploring purchase history.',created_at:created,updated_at:created});
  await putDemo('events',{id:'demo_event_active',name:'[DEMO] Riverside Pop-Up',date:activeAt.slice(0,10),location:'Riverside Market',booth_fee:45,notes:'Demo event — safe to clear in Settings.',status:realActive?'planned':'active',started_at:realActive?null:activeAt,closed_at:null,summary:null,created_at:created,updated_at:activeAt});
  await putDemo('events',{id:'demo_event_closed',name:'[DEMO] Makers Night',date:closedAt.slice(0,10),location:'Old Town Hall',booth_fee:35,notes:'Demo closed event and closeout.',status:'closed',started_at:demoDate(14,10),closed_at:closedAt,summary:null,created_at:created,updated_at:closedAt});
  for(const record of [
    {id:'demo_sale_active_named',sale_number:'DEMO-1001',event_id:'demo_event_active',customer_id:'demo_customer_maya',line_items:[{item_id:'demo_item_hoops',item_name:'[DEMO] Brass Hoops',sku:'DEMO-HOOP',quantity:1,unit_price:28},{item_id:'demo_item_tote',item_name:'[DEMO] Market Tote',sku:'DEMO-TOTE',quantity:1,unit_price:22}],discount:5,tax_rate:0,created_at:demoDate(0,10),voided_at:null},
    {id:'demo_sale_active_walkup',sale_number:'DEMO-1002',event_id:'demo_event_active',customer_id:null,line_items:[{item_id:'demo_item_candle',item_name:'[DEMO] Citrus Candle',sku:'DEMO-CANDLE',quantity:2,unit_price:18}],discount:0,tax_rate:0,created_at:demoDate(0,11),voided_at:null},
    {id:'demo_sale_closed_walkup',sale_number:'DEMO-0901',event_id:'demo_event_closed',customer_id:null,line_items:[{item_id:'demo_item_hoops',item_name:'[DEMO] Brass Hoops',sku:'DEMO-HOOP',quantity:2,unit_price:28}],discount:0,tax_rate:0,created_at:demoDate(14,13),voided_at:null},
    {id:'demo_sale_closed_named',sale_number:'DEMO-0902',event_id:'demo_event_closed',customer_id:'demo_customer_maya',line_items:[{item_id:'demo_item_candle',item_name:'[DEMO] Citrus Candle',sku:'DEMO-CANDLE',quantity:1,unit_price:18},{item_id:'demo_item_tote',item_name:'[DEMO] Market Tote',sku:'DEMO-TOTE',quantity:1,unit_price:22}],discount:0,tax_rate:0,created_at:demoDate(14,15),voided_at:null}
  ])await putDemo('sales',record);
  for(const record of [{id:'demo_payment_1001',sale_id:'demo_sale_active_named',event_id:'demo_event_active',amount:45,method:'card',created_at:demoDate(0,10)},{id:'demo_payment_1002',sale_id:'demo_sale_active_walkup',event_id:'demo_event_active',amount:36,method:'cash',created_at:demoDate(0,11)},{id:'demo_payment_0901',sale_id:'demo_sale_closed_walkup',event_id:'demo_event_closed',amount:56,method:'cash',created_at:demoDate(14,13)},{id:'demo_payment_0902',sale_id:'demo_sale_closed_named',event_id:'demo_event_closed',amount:40,method:'Venmo',created_at:demoDate(14,15)}])await putDemo('payments',record);
