async function clearDemoData(){for(const name of DATA_STORES)for(const record of await all(name))if(isDemoRecord(record))await remove(name,record.id);}

async function saveForm(form){const fd=new FormData(form),data=Object.fromEntries(fd),id=form.dataset.id;
  if(form.id==='event-form'){const old=id?await get('events',id):null;await put('events',{...old,id:id||uid('event'),name:data.name,date:data.date,location:data.location,booth_fee:num(data.booth_fee),notes:data.notes,status:old?.status||'planned',started_at:old?.started_at||null,closed_at:old?.closed_at||null,summary:old?.summary||null,created_at:old?.created_at||now(),updated_at:now()});closeDialog();toast('Event saved');return render();}
  if(form.id==='item-form'){const old=id?await get('items',id):null,photo=await fileData(form.photo.files[0]);const quantity=Math.trunc(num(data.quantity)),record={...old,id:id||uid('item'),name:data.name,sku:data.sku,price:num(data.price),category_id:data.category_id||null,photo:photo||old?.photo||null,track_quantity:data.track_quantity==='on',quantity,low_stock_at:Math.max(0,Math.trunc(num(data.low_stock_at))),active:data.active==='on',created_at:old?.created_at||now(),updated_at:now()};await put('items',record);const previous=old?.track_quantity?num(old.quantity):0;if(record.track_quantity&&quantity!==previous)await put('inventoryAdjustments',{id:uid('adj'),item_id:record.id,item_name:record.name,change:quantity-previous,reason:old?'correction':'manual adjustment',note:old?'Quantity changed while editing item':'Opening quantity',created_at:now()});closeDialog();toast('Item saved');return render();}
  if(form.id==='category-form'){await put('categories',{id:uid('category'),name:data.name,created_at:now(),updated_at:now()});closeDialog();toast('Category added');return categoryManager();}
  if(form.id==='customer-form'){const old=id?await get('customers',id):null;await put('customers',{...old,id:id||uid('customer'),name:data.name,email:data.email,phone:data.phone,notes:data.notes,created_at:old?.created_at||now(),updated_at:now()});closeDialog();toast('Customer saved');return render();}
  if(form.id==='settings-form'){for(const [key,value] of Object.entries(data))await put('settings',{id:key,value});toast('Settings saved');return render();}
  if(form.id==='adjustment-form'){const item=await get('items',data.item_id),change=Math.trunc(num(data.change));if(!item)throw new Error('Choose an item.');item.quantity=num(item.quantity)+change;item.updated_at=now();await put('items',item);await put('inventoryAdjustments',{id:uid('adj'),item_id:item.id,item_name:item.name,change,reason:data.reason,note:data.note,created_at:now()});closeDialog();toast('Inventory updated');return render();}
  if(form.id==='checkout-form'){const active=await getActive();if(!active)throw new Error('No active event.');const items=await all('items'),n=num(await setting('sale_next',1)),lines=[];for(const [itemId,quantity] of cart){const item=items.find(i=>i.id===itemId);if(!item)continue;if(item.track_quantity&&num(item.quantity)<quantity&&!confirm(`${item.name} has only ${item.quantity} in stock. Record the sale anyway?`))return;lines.push({item_id:item.id,item_name:item.name,sku:item.sku||'',quantity,unit_price:num(item.price)});}const sale={id:uid('sale'),sale_number:`SALE-${String(n).padStart(5,'0')}`,event_id:active.id,customer_id:data.customer_id||null,line_items:lines,discount:num(data.discount),tax_rate:num(data.tax_rate),created_at:now(),voided_at:null};const total=saleTotals(sale).total;await put('sales',sale);await put('payments',{id:uid('payment'),sale_id:sale.id,event_id:active.id,amount:total,method:data.method,created_at:now()});await put('settings',{id:'sale_next',value:n+1});for(const line of lines){const item=items.find(i=>i.id===line.item_id);if(item.track_quantity){item.quantity=num(item.quantity)-line.quantity;item.updated_at=now();await put('items',item);await put('inventoryAdjustments',{id:uid('adj'),item_id:item.id,item_name:item.name,change:-line.quantity,reason:'sale',sale_id:sale.id,note:sale.sale_number,created_at:now()});}}cart.clear();closeDialog();await reconcile();toast('Sale saved');return data.receipt==='on'?go('receipt',sale.id):go('sell');}
}

async function handleAction(name,el){
  if(name==='start-tour')return startTour();if(name==='skip-tour')return skipTour();if(name==='previous-tour')return moveTour(-1);if(name==='next-tour')return moveTour(1);
  if(name==='populate-demo'){await populateDemoData();toast('Demo data is ready');return render();}
  if(name==='clear-demo'){if(!confirm('Clear only BoothBoss demo data? Your real records will stay untouched.'))return;await clearDemoData();toast('Demo data cleared');return render();}
  if(name==='close-dialog')return closeDialog();if(name==='new-event')return eventForm();if(name==='edit-event')return eventForm(await get('events',el.dataset.id));if(name==='new-item')return itemForm();if(name==='edit-item')return itemForm(await get('items',el.dataset.id));if(name==='manage-categories')return categoryManager();if(name==='new-customer')return customerForm();if(name==='edit-customer')return customerForm(await get('customers',el.dataset.id));if(name==='new-adjustment')return adjustmentForm();
  if(name==='start-event'||name==='reopen-event'){const current=await getActive();if(current&&current.id!==el.dataset.id){if(!confirm(`Close ${current.name} and open this event?`))return;current.status='closed';current.closed_at=now();current.updated_at=now();await put('events',current);}const event=await get('events',el.dataset.id);event.status='active';event.started_at=event.started_at||now();event.closed_at=null;event.updated_at=now();await put('events',event);await reconcile();toast('Event started');return go('sell');}
  if(name==='close-event'){if(!confirm('Close this event and finalize its current closeout? You can reopen it later.'))return;const event=await get('events',el.dataset.id);event.status='closed';event.closed_at=now();event.updated_at=now();await put('events',event);await reconcile();toast('Event closed');return render();}
  if(name==='delete-record'){if(el.dataset.store==='events'&&(await all('sales')).some(s=>s.event_id===el.dataset.id))return toast('Events with sales cannot be deleted');if(!confirm(`Delete this ${el.dataset.store.slice(0,-1)}? This cannot be undone.`))return;await remove(el.dataset.store,el.dataset.id);closeDialog();toast('Record deleted');return go(el.dataset.store==='events'?'events':el.dataset.store==='customers'?'customers':'catalog');}
  if(name==='delete-category'){const used=(await all('items')).some(i=>i.category_id===el.dataset.id);if(used)return toast('Move items out of this category first');if(!confirm('Delete this category?'))return;await remove('categories',el.dataset.id);closeDialog();return categoryManager();}
  if(name==='add-cart'){cart.set(el.dataset.id,(cart.get(el.dataset.id)||0)+1);return refreshCart();}if(name==='cart-plus'){cart.set(el.dataset.id,(cart.get(el.dataset.id)||0)+1);return refreshCart();}if(name==='cart-minus'){const q=(cart.get(el.dataset.id)||0)-1;q>0?cart.set(el.dataset.id,q):cart.delete(el.dataset.id);return refreshCart();}if(name==='clear-cart'){if(cart.size&&confirm('Clear the current sale?')){cart.clear();refreshCart();}return;}if(name==='checkout')return checkoutForm();
  if(name==='filter-sale'){document.querySelectorAll('#sell-tabs button').forEach(b=>b.classList.toggle('active',b===el));filterProducts();return;}if(name==='backup')return backup();if(name==='export-csv')return exportCSV(el.dataset.store);
  if(name==='share-receipt'){const text=await receiptText(el.dataset.id);if(navigator.share)try{return await navigator.share({title:'BoothBoss receipt',text});}catch(error){if(error.name==='AbortError')return;}download(`${el.dataset.id}.txt`,text);return toast('Receipt downloaded');}if(name==='download-receipt'){download(`${el.dataset.id}.txt`,await receiptText(el.dataset.id));return toast('Receipt downloaded');}
}
function filterProducts(){const q=(document.querySelector('#sell-search')?.value||'').toLowerCase(),category=document.querySelector('#sell-tabs .active')?.dataset.filter||'all';document.querySelectorAll('#product-grid .product').forEach(p=>p.hidden=!(p.dataset.search.includes(q)&&(category==='all'||p.dataset.category===category)));}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return;}const open=e.target.closest('[data-open]');if(open){const [page,id]=open.dataset.open.split(':');go(page,id);return;}const action=e.target.closest('[data-action]');if(action)try{await handleAction(action.dataset.action,action);}catch(error){console.error(error);toast(`Could not complete: ${error.message}`);}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='search-form'){go('search',encodeURIComponent(new FormData(e.target).get('q').trim()));return;}await saveForm(e.target);}catch(error){console.error(error);toast(`Could not save: ${error.message}`);}});
document.addEventListener('input',e=>{if(e.target.id==='sell-search')filterProducts();if(e.target.id==='catalog-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('#catalog-list [data-search]').forEach(x=>x.hidden=!x.dataset.search.includes(q));}});
document.addEventListener('change',e=>{if(e.target.id==='restore-file'&&e.target.files[0])restore(e.target.files[0]);});
window.addEventListener('hashchange',route);window.addEventListener('online',()=>document.querySelector('#offline').hidden=true);window.addEventListener('offline',()=>document.querySelector('#offline').hidden=false);document.addEventListener('visibilitychange',async()=>{if(document.visibilityState==='visible'&&db){await reconcile();render();}});

async function init(){db=await openDB();if(!(await setting('initialized',false))){await put('settings',{id:'initialized',value:true});await put('settings',{id:'sale_next',value:1});await put('settings',{id:'tax_rate',value:0});await put('settings',{id:'receipt_footer',value:'Thanks for shopping small!'});}await reconcile();document.querySelector('#offline').hidden=navigator.onLine;if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');await route();}
window.BoothBoss={openDB,all,get,put,clear,snapshot,reconcile,saleTotals,eventSummary,validateBackup,populateDemoData,clearDemoData,startTour,skipTour,STORES};
init().catch(error=>{console.error(error);app.innerHTML=`<div class="notice">BoothBoss could not open local storage: ${esc(error.message)}</div>`;});
